from qiskit import QuantumCircuit
import numpy as np
from qiskit.circuit.library import ZGate

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    if L >= 1 << n:          # flipping all states is a global phase
        return qc

    # for each set bit of L we create the dyadic interval
    # x < L  <=>  for some i with L_i=1 : higher bits = L, bit i =0
    for i in range(n):
        if ((L >> i) & 1) == 0:
            continue

        target = n - 1
        # X on qubits where desired value is 0
        for j in range(i, n):
            desired = 0 if j == i else ((L >> j) & 1)
            if desired == 0:
                qc.x(j)

        controls = [j for j in range(i, n) if j != target]
        if len(controls) == 0:
            qc.z(target)
        else:
            qc.mcp(np.pi, controls, target)

        # uncompute X
        for j in range(i, n):
            desired = 0 if j == i else ((L >> j) & 1)
            if desired == 0:
                qc.x(j)

    return qc

from qiskit import QuantumCircuit
from qiskit.circuit.library import ZGate

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    if L <= 0 or L >= 1 << n:
        return qc

    for i in range(n):
        if ((L >> i) & 1) == 0:
            continue

        # X on j>i where L_j == 0  -> map x_j = L_j to 1
        for j in range(i + 1, n):
            if ((L >> j) & 1) == 0:
                qc.x(j)

        # map x_i = 0 to 1
        qc.x(i)

        controls = list(range(i + 1, n))
        if len(controls) == 0:
            qc.z(i)
        else:
            gate = ZGate().control(len(controls))
            qc.append(gate, controls + [i])

        # uncompute
        qc.x(i)
        for j in range(i + 1, n):
            if ((L >> j) & 1) == 0:
                qc.x(j)

    return qc

from qiskit import QuantumCircuit
from qiskit.circuit.library import MCPhaseGate
import numpy as np

def solve(n: int, L: int) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    if L <= 0 or L >= 1 << n:
        return qc

    for i in range(n):
        if ((L >> i) & 1) == 0:
            continue

        # controls are the qubits i .. n-1
        controls = list(range(i, n))
        # map desired pattern to all 1s
        for j in controls:
            desired = 0 if j == i else (L >> j) & 1
            if desired == 0:
                qc.x(j)

        # multi controlled phase π on the whole interval
        gate = MCPhaseGate(np.pi, len(controls))
        qc.append(gate, controls)

        # uncompute
        for j in controls:
            desired = 0 if j == i else (L >> j) & 1
            if desired == 0:
                qc.x(j)

    return qc
